function stippleProcess(data,w,h,opts){
  opts=opts||{};
  var density=opts.density!=null?opts.density:6;
  var invert=opts.invert?1:0;
  if(density<2)density=2; else if(density>20)density=20;
  var out=new Uint8ClampedArray(data.length);
  for(var i=0;i<out.length;i+=4){ out[i]=255; out[i+1]=255; out[i+2]=255; out[i+3]=255; }
  function lum(x,y){ var p=(y*w+x)*4; return 0.299*data[p]+0.587*data[p+1]+0.114*data[p+2]; }
  for(var cy=0;cy<h;cy+=density) for(var cx=0;cx<w;cx+=density){
    var c=Math.min(density, w-cx), r=Math.min(density, h-cy);
    var sum=0,n=0;
    for(var yy=cy;yy<cy+r;yy++) for(var xx=cx;xx<cx+c;xx++){ sum+=lum(xx,yy); n++; }
    var dark=invert? sum/n : 255-sum/n;
    if(dark<20) continue;
    var rad=dark/255*(density*0.6);
    var ccx=cx+c/2, ccy=cy+r/2;
    var x0=Math.max(0,Math.floor(ccx-rad)), x1=Math.min(w-1,Math.ceil(ccx+rad));
    var y0=Math.max(0,Math.floor(ccy-rad)), y1=Math.min(h-1,Math.ceil(ccy+rad));
    for(var py=y0;py<=y1;py++) for(var px=x0;px<=x1;px++){
      var ddx=px-ccx, ddy=py-ccy;
      if(ddx*ddx+ddy*ddy<=rad*rad){ var pp=(py*w+px)*4; out[pp]=0; out[pp+1]=0; out[pp+2]=0; }
    }
  }
  return out;
}

var EXPORTS={stippleProcess:stippleProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.StippleForgePure = EXPORTS; }
